import {stations,stationLabel,stationByCode,findTrains,validateSearch,formatDuration} from './schedules.js';
const $=id=>document.getElementById(id);
$('stations').innerHTML=stations.map(s=>`<option value="${stationLabel(s.code)}"></option>`).join('');
let current=[];
function dayTag(day){return day>0?`<span class="day-label">+${day} day${day>1?'s':''}</span>`:'';}
function stopTime(stop,kind,base){return stop[kind]?`${stop[kind]}${dayTag(stop[`${kind}Day`]-base)}`:'—';}
function render(){const ordered=[...current].sort((a,b)=>$('sort').value==='duration'?a.duration-b.duration:a.departure.departure.localeCompare(b.departure.departure));
 $('results').innerHTML=ordered.length?ordered.map(t=>{const intermediate=t.segment.length-2;return `<article class="train-card"><div class="train-main"><div><p class="train-number">${t.number} · SAMPLE SERVICE</p><h3 class="train-name">${t.name}</h3><span class="train-type">${t.type}</span></div><div class="journey"><div><div class="time">${t.departure.departure}</div><div class="station-code">${t.departure.code}</div></div><div class="journey-middle"><span>${formatDuration(t.duration)}</span><div class="route-line"></div><span>${intermediate?`${intermediate} stop${intermediate>1?'s':''}`:'Non-stop'}</span></div><div class="arrival"><div class="time">${t.arrival.arrival}${dayTag(t.dayDifference)}</div><div class="station-code">${t.arrival.code}</div></div></div><div class="train-right"><strong>Scheduled service</strong>All times in IST</div></div><details><summary aria-label="View route and station stops for ${t.name}"><span>View route & station stops</span></summary><div class="stops"><div class="stop-heading"><span>STATION · SELECTED JOURNEY</span><span>ARRIVAL</span><span>DEPARTURE</span></div>${t.segment.map(s=>`<div class="stop-row"><div class="stop-name">${stationByCode(s.code).name}<small>${s.code}</small></div><div>${stopTime(s,'arrival',t.departure.departureDay)}</div><div>${stopTime(s,'departure',t.departure.departureDay)}</div></div>`).join('')}</div></details></article>`;}).join(''):'<div class="empty"><h3>No sample trains on this route</h3><p>Try a suggested journey above, or swap your stations.</p></div>';
}
function search(){const checked=validateSearch($('from').value,$('to').value);$('form-error').hidden=!checked.error;$('from').removeAttribute('aria-invalid');$('to').removeAttribute('aria-invalid');if(checked.error){$('form-error').textContent=checked.error;const target=!$('from').value.trim()?'from':'to';$(target).setAttribute('aria-invalid','true');$(target).focus();return;}const {from,to}=checked;$('from').value=stationLabel(from.code);$('to').value=stationLabel(to.code);$('results-title').replaceChildren(document.createTextNode(from.name+' '),Object.assign(document.createElement('span'),{textContent:'→'}),document.createTextNode(' '+to.name));current=findTrains(from.code,to.code);$('results-count').textContent=`${current.length} sample train${current.length===1?'':'s'} found · Illustrative schedules · All times IST`;render();}
$('search-form').addEventListener('submit',event=>{event.preventDefault();search();});
$('swap').addEventListener('click',()=>{const previous=$('from').value;$('from').value=$('to').value;$('to').value=previous;if($('from').value.trim()&&$('to').value.trim())search();});
$('sort').addEventListener('change',render);
document.querySelectorAll('[data-route]').forEach(button=>button.addEventListener('click',()=>{const [from,to]=button.dataset.route.split(',');$('from').value=stationLabel(from);$('to').value=stationLabel(to);search();}));
search();
